  1	/* ============================================================
  2	   views/knowledge.js — Knowledge view
  3	   Section 4f of the MCP Server Dashboard SPA
  4	   Depends on: API, escapeHtml, formatDate, showLoading, showError
  5	   ============================================================ */
  6	
  7	function renderKnowledge(app) {
  8	  showLoading(app);
  9	
 10	  /* ── Confidence bucket thresholds ────────────────────────── */
 11	  var CONFIDENCE_HIGH_MIN   = 68;   /* 68–100 → High  */
 12	  var CONFIDENCE_MEDIUM_MIN = 34;   /* 34–67  → Medium */
 13	  /* 0–33 → Low */
 14	
 15	  /* ── View state ──────────────────────────────────────────── */
 16	  var allInsights     = [];
 17	  var activeTab       = 'global';   /* 'global' | 'project' */
 18	  var filterCategory  = '';
 19	  var filterProject   = '';
 20	  var filterQuery     = '';
 21	  var editingId       = null;       /* numeric id of card in edit mode */
 22	  var confirmDeleteId = null;       /* numeric id of card in delete-confirm mode */
 23	  var movingId        = null;       /* numeric id of card in move mode */
 24	
 25	  /* ── formatConfidence ────────────────────────────────────── */
 26	  function formatConfidence(value) {
 27	    var pct = Math.round(value * 100);
 28	    var label;
 29	    if (pct >= CONFIDENCE_HIGH_MIN) {
 30	      label = 'High';
 31	    } else if (pct >= CONFIDENCE_MEDIUM_MIN) {
 32	      label = 'Medium';
 33	    } else {
 34	      label = 'Low';
 35	    }
 36	    return pct + '% (' + label + ')';
 37	  }
 38	
 39	  /* ── applyFilters ────────────────────────────────────────── */
 40	  function applyFilters() {
 41	    var scopeValue = activeTab === 'global' ? 'global' : 'project';
 42	    return allInsights.filter(function (ins) {
 43	      if (ins.scope !== scopeValue) return false;
 44	      if (filterCategory && ins.category !== filterCategory) return false;
 45	      if (activeTab === 'project' && filterProject && ins.project_slug !== filterProject) return false;
 46	      if (filterQuery) {
 47	        var q = filterQuery.toLowerCase();
 48	        var titleMatch    = ins.title   && ins.title.toLowerCase().indexOf(q) !== -1;
 49	        var contentMatch  = ins.content && ins.content.toLowerCase().indexOf(q) !== -1;
 50	        var tagsMatch     = ins.tags    && ins.tags.some(function (t) { return t.toLowerCase().indexOf(q) !== -1; });
 51	        if (!titleMatch && !contentMatch && !tagsMatch) return false;
 52	      }
 53	      return true;
 54	    });
 55	  }
 56	
 57	  /* ── getDistinctValues ───────────────────────────────────── */
 58	  function getDistinctValues(insights) {
 59	    var categories = [];
 60	    var projects   = [];
 61	    insights.forEach(function (ins) {
 62	      if (ins.category     && categories.indexOf(ins.category)     === -1) categories.push(ins.category);
 63	      if (ins.project_slug && projects.indexOf(ins.project_slug)   === -1) projects.push(ins.project_slug);
 64	    });
 65	    categories.sort();
 66	    projects.sort();
 67	    return { categories: categories, projects: projects };
 68	  }
 69	
 70	  /* ── buildFilterBarHtml ──────────────────────────────────── */
 71	  function buildFilterBarHtml(categories, projects) {
 72	    var catOptions = categories.map(function (c) {
 73	      return '<option value="' + escapeHtml(c) + '"' + (filterCategory === c ? ' selected' : '') + '>' + escapeHtml(c) + '</option>';
 74	    }).join('');
 75	
 76	    var baseBar =
 77	      '<label for="kn-category">Category:</label>' +
 78	      '<select id="kn-category" class="form-control form-control-sm">' +
 79	        '<option value="">All categories</option>' + catOptions +
 80	      '</select>' +
 81	      '<label for="kn-query">Search:</label>' +
 82	      '<input id="kn-query" type="text" class="form-control form-control-sm" placeholder="Title, content or tag…" value="' + escapeHtml(filterQuery) + '">';
 83	
 84	    if (activeTab === 'project') {
 85	      var projOptions = projects.map(function (p) {
 86	        return '<option value="' + escapeHtml(p) + '"' + (filterProject === p ? ' selected' : '') + '>' + escapeHtml(p) + '</option>';
 87	      }).join('');
 88	      return (
 89	        '<label for="kn-project">Project:</label>' +
 90	        '<select id="kn-project" class="form-control form-control-sm">' +
 91	          '<option value="">All projects</option>' + projOptions +
 92	        '</select>' +
 93	        baseBar
 94	      );
 95	    }
 96	
 97	    return baseBar;
 98	  }
 99	
100	  /* ── buildKnowledgeHtml ──────────────────────────────────── */

101	  function buildKnowledgeHtml(insights) {
102	    if (!insights.length) {
103	      return '<p class="text-muted mt-16">No knowledge entries found.</p>';
104	    }
105	
106	    return insights.map(function (ins) {
107	      var id          = ins.id;
108	      var isGlobal    = ins.scope === 'global';
109	      var isEditing   = editingId === id;
110	      var isConfirm   = confirmDeleteId === id;
111	      var isMoving    = movingId === id;
112	
113	      /* ── Scope badge ── */
114	      var scopeBadgeClass = isGlobal ? 'badge badge-scope-global' : 'badge badge-scope-project';
115	      var scopeLabel      = isGlobal ? 'Global' : 'Project';
116	
117	      /* ── Tags ── */
118	      var tagsHtml = '';
119	      if (ins.tags && ins.tags.length) {
120	        tagsHtml = ins.tags.map(function (t) {
121	          return '<span class="tag-chip">' + escapeHtml(t) + '</span>';
122	        }).join(' ');
123	      }
124	
125	      /* ── Content preview ── */
126	      var preview = ins.content ? ins.content.slice(0, 200) + (ins.content.length > 200 ? '…' : '') : '';
127	
128	      /* ── Superseded-by notice ── */
129	      var supersededHtml = ins.superseded_by != null
130	        ? '<p class="text-muted" style="font-size:12px">Superseded by KN-' + ins.superseded_by + '</p>'
131	        : '';
132	
133	      /* ── Inline edit form ── */
134	      if (isEditing) {
135	        var tagsValue = ins.tags ? ins.tags.join(', ') : '';
136	        var confPct   = formatConfidence(ins.confidence != null ? ins.confidence : 0);
137	        return '<div class="card" data-id="' + id + '">' +
138	          '<form id="kn-edit-form-' + id + '">' +
139	            '<div class="form-group">' +
140	              '<label class="form-label">Title</label>' +
141	              '<input id="kn-edit-title-' + id + '" class="form-control" type="text" value="' + escapeHtml(ins.title || '') + '">' +
142	            '</div>' +
143	            '<div class="form-group">' +
144	              '<label class="form-label">Content</label>' +
145	              '<textarea id="kn-edit-content-' + id + '" class="form-control" rows="6">' + escapeHtml(ins.content || '') + '</textarea>' +
146	            '</div>' +
147	            '<div class="form-group">' +
148	              '<label class="form-label">Category</label>' +
149	              '<input id="kn-edit-category-' + id + '" class="form-control" type="text" value="' + escapeHtml(ins.category || '') + '">' +
150	            '</div>' +
151	            '<div class="form-group">' +
152	              '<label class="form-label">Tags (comma-separated)</label>' +
153	              '<input id="kn-edit-tags-' + id + '" class="form-control" type="text" value="' + escapeHtml(tagsValue) + '">' +
154	            '</div>' +
155	            '<div class="form-group">' +
156	              '<label class="form-label">Confidence: <span id="kn-conf-label-' + id + '">' + escapeHtml(confPct) + '</span></label>' +
157	              '<input id="kn-edit-conf-' + id + '" class="form-control" type="range" min="0" max="1" step="0.01" value="' + (ins.confidence != null ? ins.confidence : 0) + '">' +
158	            '</div>' +
159	            '<div class="knowledge-actions">' +
160	              '<button type="submit" class="btn btn-primary btn-sm">Save</button>' +
161	              '<button type="button" class="btn btn-sm" data-action="cancel-edit" data-id="' + id + '">Cancel</button>' +
162	            '</div>' +
163	            '<div id="kn-edit-msg-' + id + '"></div>' +
164	          '</form>' +
165	        '</div>';
166	      }
167	
168	      /* ── Action buttons ── */
169	      var deleteHtml;
170	      if (isConfirm) {
171	        deleteHtml =
172	          '<span>Delete this entry?</span>' +
173	          '<button class="btn btn-danger btn-sm" data-action="confirm-delete" data-id="' + id + '" data-scope="' + escapeHtml(ins.scope) + '" data-slug="' + escapeHtml(ins.project_slug || '') + '">Confirm</button>' +
174	          '<button class="btn btn-sm" data-action="cancel-delete" data-id="' + id + '">Cancel</button>';
175	      } else {
176	        deleteHtml = '<button class="btn btn-danger btn-sm" data-action="delete" data-id="' + id + '">Delete</button>';
177	      }
178	
179	      var promoteHtml = !isGlobal
180	        ? '<button class="btn btn-sm" data-action="promote" data-id="' + id + '" data-scope="' + escapeHtml(ins.scope) + '" data-slug="' + escapeHtml(ins.project_slug || '') + '">Promote to Global</button>'
181	        : '';
182	
183	      var moveHtml;
184	      if (isMoving) {
185	        moveHtml =
186	          '<span class="knowledge-move-input">' +
187	            '<input id="kn-move-slug-' + id + '" class="form-control form-control-sm" type="text" placeholder="target-project-slug">' +
188	            '<button class="btn btn-primary btn-sm" data-action="confirm-move" data-id="' + id + '" data-scope="' + escapeHtml(ins.scope) + '" data-slug="' + escapeHtml(ins.project_slug || '') + '">Confirm</button>' +
189	            '<button class="btn btn-sm" data-action="cancel-move" data-id="' + id + '">Cancel</button>' +
190	          '</span>';
191	      } else {
192	        moveHtml = '<button class="btn btn-sm" data-action="move" data-id="' + id + '">Move to Project</button>';
193	      }
194	
195	      return '<div class="card" data-id="' + id + '">' +
196	        '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px">' +
197	          '<span class="' + scopeBadgeClass + '">' + scopeLabel + '</span>' +
198	          (ins.category ? '<span class="category-pill">' + escapeHtml(ins.category) + '</span>' : '') +
199	          (ins.project_slug ? '<span class="text-muted" style="font-size:12px">' + escapeHtml(ins.project_slug) + '</span>' : '') +
200	        '</div>' +
201	        '<h3 style="margin:0 0 6px 0;font-size:15px">' + escapeHtml(ins.title || '(no title)') + '</h3>' +
202	        (tagsHtml ? '<div style="margin-bottom:6px">' + tagsHtml + '</div>' : '') +
203	        (preview ? '<p style="margin:0 0 6px 0;color:var(--color-text-muted);font-size:13px">' + escapeHtml(preview) + '</p>' : '') +
204	        '<div style="display:flex;align-items:center;gap:16px;font-size:12px;color:var(--color-text-muted);margin-bottom:4px">' +
205	          '<span class="confidence-label">Confidence: ' + escapeHtml(ins.confidence != null ? formatConfidence(ins.confidence) : '—') + '</span>' +
206	          (ins.source ? '<span>Source: ' + escapeHtml(ins.source) + '</span>' : '') +
207	        '</div>' +
208	        '<div style="font-size:11px;color:var(--color-text-muted);margin-bottom:8px">' +
209	          'Created: ' + escapeHtml(formatDate(ins.created_at)) +
210	          ' &nbsp;·&nbsp; Updated: ' + escapeHtml(formatDate(ins.updated_at)) +
211	        '</div>' +
