223	  /* ── render ──────────────────────────────────────────────── */
224	  function render(insights) {
225	    allInsights = insights;
226	
227	    var vals     = getDistinctValues(insights);
228	    var categories = vals.categories;
229	    var projects   = vals.projects;
230	
231	    var filtered = applyFilters();
232	
233	    app.innerHTML =
234	      '<div class="page-header"><h1>Knowledge</h1></div>' +
235	      '<div class="knowledge-tabs">' +
236	        '<button class="knowledge-tab' + (activeTab === 'global' ? ' active' : '') + '" data-tab="global">Global</button>' +
237	        '<button class="knowledge-tab' + (activeTab === 'project' ? ' active' : '') + '" data-tab="project">Repository</button>' +
238	      '</div>' +
239	      '<div class="filter-bar" id="kn-filter-bar">' +
240	        buildFilterBarHtml(categories, projects) +
241	      '</div>' +
242	      '<div id="knowledge-list">' + buildKnowledgeHtml(filtered) + '</div>';
243	
244	    wireEvents(categories, projects);
245	    wireRangeSliders();
246	  }
